import{c as a,Q as t,j as e,m as p}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E5%8D%95%E6%AC%A1%E8%BF%AD%E4%BB%A3%E5%86%85%E7%9A%848%E4%B8%AAdatablock%E8%BF%9B%E8%A1%8CExp%E8%AE%A1%E7%AE%97%E7%A4%BA%E6%84%8F%E5%9B%BE.DAgqKbkj.png",i="/assets/2%E6%AC%A1%E8%BF%AD%E4%BB%A3Exp%E8%AE%A1%E7%AE%97.PYkZs7X5.png",l="/assets/%E9%80%9A%E8%BF%87mask%E5%8F%82%E6%95%B0%E8%BF%9B%E8%A1%8C%E6%8E%A9%E7%A0%81%E6%93%8D%E4%BD%9C%E7%A4%BA%E6%84%8F%E5%9B%BE%EF%BC%88%E4%BB%A5float%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%E4%B8%BA%E4%BE%8B%EF%BC%89.CgTKNRsG.png",r="/assets/%E5%8D%95%E6%AC%A1%E8%BF%AD%E4%BB%A3%E5%86%85%E9%9D%9E%E8%BF%9E%E7%BB%AD%E5%9C%BA%E6%99%AF%E7%9A%84%E7%A4%BA%E6%84%8F%E5%9B%BE.DWPDeWms.png",c="/assets/%E5%A4%9A%E6%AC%A1%E8%BF%AD%E4%BB%A3%E9%97%B4%E9%9D%9E%E8%BF%9E%E7%BB%AD%E5%9C%BA%E6%99%AF%E7%9A%84%E7%A4%BA%E6%84%8F%E5%9B%BE.D2haXsu0.png",d="/assets/dataBlockStride%E4%B8%8D%E5%90%8C%E5%8F%96%E5%80%BC%E4%B8%BE%E4%BE%8B.DCkjCO9X.png",o="/assets/repeat_stride1.Ch_8kF1p.png",g="/assets/repeat_stride2.CUVormYc.png",k="/assets/repeat_stride3.CEjddVEk.png",m="/assets/repeat_stride4.BMSO1F4d.png",E="/assets/mask.DL4StDFY.png",B="/assets/mask_32bit.C5wFcOOJ.png",f=JSON.parse('{"title":"高维切分API","description":"","frontmatter":{},"headers":[{"level":1,"title":"高维切分API","slug":"高维切分api"},{"level":2,"title":"dataBlockStride","slug":"datablockstride"},{"level":2,"title":"repeatStride","slug":"repeatstride"},{"level":2,"title":"mask参数","slug":"mask参数"}],"relativePath":"guide/编程指南/类库API/基础API/接口分类说明/高维切分API.md","filePath":"guide/编程指南/类库API/基础API/接口分类说明/高维切分API.md"}'),b={name:"guide/编程指南/类库API/基础API/接口分类说明/高维切分API.md"};function u(h,s,A,S,_,v){return t(),e("div",null,[...s[0]||(s[0]=[p('<h1 id="高维切分api" tabindex="-1">高维切分API <a class="header-anchor" href="#高维切分api" aria-label="Permalink to &quot;高维切分API&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>本章节对<strong>矢量计算基础API</strong>中的<strong>tensor高维切分计算</strong>接口做解释说明。如果您不需要使用此类接口，可略过该章节。</li><li>下文中的repeatTime、dataBlockStride、repeatStride、mask为通用描述，其命名不一定与具体指令中的参数命名完全对应。 比如，单次迭代内不同datablock间地址步长dataBlockStride参数，在单目API中，对应为dstBlkStride、srcBlkStride参数；在双目API中，对应为dstBlkStride、src0BlkStride、src1BlkStride参数。 您可以在具体接口的参数说明中，找到参数含义的描述。</li></ul></div><p>使用<strong>tensor高维切分计算</strong>API可充分发挥硬件优势，支持开发者控制指令的<strong>迭代执行</strong>和操作数的<strong>地址间隔</strong>，功能更加灵活。</p><p>矢量计算通过Vector计算单元完成，矢量计算的源操作数和目的操作数均通过Unified Buffer（UB）来进行存储。Vector计算单元每个迭代会从UB中取出<strong>8</strong>个<strong>datablock</strong>（每个datablock数据块内部地址连续，长度32Byte），进行计算，并写入对应的8个datablock中。下图为单次迭代内的8个datablock进行Exp计算的示意图。</p><p><strong>图 1</strong> 单次迭代内的8个datablock进行Exp计算示意图<br><img src="'+n+'" alt="" title="单次迭代内的8个datablock进行Exp计算示意图"></p><ul><li><p>矢量计算API支持开发者通过<strong>repeatTime</strong>来配置迭代次数，从而控制指令的多次迭代执行。假设repeatTime设置为2，矢量计算单元会进行2个迭代的计算，可计算出2 * 8（每个迭代8个datablock） * 32Byte（每个datablock32Byte） = 512Byte的结果。如果数据类型为half，则计算了256个元素。下图展示了2次迭代Exp计算的示意图。由于硬件限制，<strong>repeatTime不能超过255。</strong></p><p><strong>图 2</strong> 2次迭代Exp计算<br><img src="'+i+'" alt="" title="2次迭代Exp计算"></p></li><li><p>针对同一个迭代中的数据，可以通过<strong>mask</strong>参数进行掩码操作来控制实际参与计算的个数。下图为进行Abs计算时通过mask逐比特模式按位控制哪些元素参与计算的示意图，1表示参与计算，0表示不参与计算。</p><p><strong>图 3</strong> 通过<strong>mask</strong>参数进行掩码操作示意图（以float数据类型为例）<br><img src="'+l+'" alt="" title="通过mask参数进行掩码操作示意图（以float数据类型为例）"></p></li><li><p>矢量计算单元还支持带间隔的向量计算，通过<strong>dataBlockStride</strong>（单次迭代内不同datablock间地址步长）和<strong>repeatStride</strong>（相邻迭代间相同datablock的地址步长）来进行配置。</p><ul><li><p><strong>dataBlockStride</strong></p><p>如果需要控制单次迭代内，数据处理的步长，可以通过设置同一迭代内不同datablock的地址步长dataBlockStride来实现。下图给出了单次迭代内非连续场景的示意图，示例中源操作数的dataBlockStride配置为2，表示单次迭代内不同datablock间地址步长（起始地址之间的间隔）为2个datablock。</p><p><strong>图 4</strong> 单次迭代内非连续场景的示意图<br><img src="'+r+'" alt="" title="单次迭代内非连续场景的示意图"></p></li><li><p><strong>repeatStride</strong></p><p>当repeatTime大于1，需要多次迭代完成矢量计算时，您可以根据不同的使用场景合理设置相邻迭代间相同datablock的地址步长repeatStride的值。</p><p>下图给出了多次迭代间非连续场景的示意图，示例中源操作数和目的操作数的<strong>repeatStride</strong>均配置为9，表示相邻迭代间相同datablock起始地址之间的间隔为9个datablock。相同datablock是指datablock在迭代内的位置相同，比如下图中的src1和src9处于相邻迭代，在迭代内都是第一个datablock的位置，其间隔即为<strong>repeatStride</strong>的数值。</p><p><strong>图 5</strong> 多次迭代间非连续场景的示意图<br><img src="'+c+'" alt="" title="多次迭代间非连续场景的示意图"></p></li></ul></li></ul><p>下文中给出了dataBlockStride、repeatStride、mask的详细配置说明和示例。</p><h2 id="datablockstride" tabindex="-1">dataBlockStride <a class="header-anchor" href="#datablockstride" aria-label="Permalink to &quot;dataBlockStride&quot;">​</a></h2><p>dataBlockStride是指同一迭代内不同datablock的地址步长。</p><ul><li><p>连续计算，dataBlockStride设置为1，对同一迭代内的8个datablock数据连续进行处理。</p></li><li><p>非连续计算，dataBlockStride值大于1（如取2），同一迭代内不同datablock之间在读取数据时出现一个datablock的间隔，如下图所示。</p><p><strong>图 6</strong> dataBlockStride不同取值举例<br><img src="'+d+'" alt="" title="dataBlockStride不同取值举例"></p></li></ul><h2 id="repeatstride" tabindex="-1">repeatStride <a class="header-anchor" href="#repeatstride" aria-label="Permalink to &quot;repeatStride&quot;">​</a></h2><p>repeatStride是指相邻迭代间相同datablock的地址步长。</p><ul><li><p><strong>连续计算场景</strong>：假设定义一个Tensor供目的操作数和源操作数同时使用（即地址重叠），repeatStride取值为8。此时，矢量计算单元第一次迭代读取连续8个datablock，第二轮迭代读取下一个连续的8个datablock，通过多次迭代即可完成所有输入数据的计算。</p><p><img src="'+o+'" alt=""></p></li><li><p><strong>非连续计算场景</strong>：repeatStride取值大于8（如取10）时，则相邻迭代间矢量计算单元读取的数据在地址上不连续，出现2个datablock的间隔。</p><p><img src="'+g+'" alt=""></p></li><li><p><strong>反复计算场景</strong>：repeatStride取值为0时，矢量计算单元会对首个连续的8个datablock进行反复读取和计算。</p><p><img src="'+k+'" alt=""></p></li><li><p><strong>部分重复计算</strong>：repeatStride取值大于0且小于8时，相邻迭代间部分数据会被矢量计算单元重复读取和计算，此种情形一般场景不涉及。</p><p><img src="'+m+`" alt=""></p></li></ul><h2 id="mask参数" tabindex="-1">mask参数 <a class="header-anchor" href="#mask参数" aria-label="Permalink to &quot;mask参数&quot;">​</a></h2><p>mask用于控制每次迭代内参与计算的元素。可通过连续模式和逐bit模式两种方式进行设置。</p><ul><li><p>连续模式：表示前面连续的多少个元素参与计算。数据类型为uint64_t。取值范围和源操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同（当前数据类型单次迭代时能处理的元素个数最大值为：256 / sizeof(数据类型)）。当操作数的数据类型占bit位16位时（如half/uint16_t），mask∈[1, 128]；当操作数为32位时（如float/int32_t），mask∈[1, 64]。</p><p>具体样例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// int16_t数据类型单次迭代能处理的元素个数最大值为256/sizeof(int16_t) = 128，mask = 64，mask∈[1, 128]，所以是合法输入</span></span>
<span class="line"><span>// repeatTime = 1, 共128个元素，单次迭代能处理128个元素，故repeatTime = 1</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内连续读取和写入数据</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 迭代间的数据连续读取和写入</span></span>
<span class="line"><span>uint64_t mask = 64;</span></span>
<span class="line"><span>AscendC::Add(dstLocal, src0Local, src1Local, mask, 1, { 1, 1, 1, 8, 8, 8 });</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local): [1 2 3 ... 64 ...128]</span></span>
<span class="line"><span>输入数据(src1Local): [1 2 3 ... 64 ...128]</span></span>
<span class="line"><span>输出数据(dstLocal): [2 4 6 ... 128 undefined...undefined]</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// int32_t数据类型单次迭代能处理的元素个数最大值为256/sizeof(int32_t) = 64，mask = 64，mask∈[1, 64]，所以是合法输入</span></span>
<span class="line"><span>// repeatTime = 1, 共64个元素，单次迭代能处理64个元素，故repeatTime = 1</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内连续读取和写入数据</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 迭代间的数据连续读取和写入</span></span>
<span class="line"><span>uint64_t mask = 64;</span></span>
<span class="line"><span>AscendC::Add(dstLocal, src0Local, src1Local, mask, 1, { 1, 1, 1, 8, 8, 8 });</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local): [1 2 3 ... 64]</span></span>
<span class="line"><span>输入数据(src1Local): [1 2 3 ... 64]</span></span>
<span class="line"><span>输出数据(dstLocal): [2 4 6 ... 128]</span></span></code></pre></div></li><li><p>逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。</p><p>mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 2&lt;sup&gt;64&lt;/sup&gt;-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 2&lt;sup&gt;64&lt;/sup&gt;-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 2&lt;sup&gt;32&lt;/sup&gt;-1]。</p><p>具体样例如下:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 数据类型为int16_t</span></span>
<span class="line"><span>uint64_t mask[2] = {6148914691236517205, 6148914691236517205};</span></span>
<span class="line"><span>// repeatTime = 1, 共128个元素，单次迭代能处理128个元素，故repeatTime = 1。</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内连续读取和写入数据。</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 迭代间的数据连续读取和写入。</span></span>
<span class="line"><span>AscendC::Add(dstLocal, src0Local, src1Local, mask, 1, { 1, 1, 1, 8, 8, 8 });</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local): [1 2 3 ... 64 ...127 128]</span></span>
<span class="line"><span>输入数据(src1Local): [1 2 3 ... 64 ...127 128]</span></span>
<span class="line"><span>输出数据(dstLocal): [2 undefined 6 ... undefined ...254 undefined]</span></span></code></pre></div><p>mask过程如下：</p><p>mask={6148914691236517205, 6148914691236517205}（注：6148914691236517205表示64位二进制数0b010101....01，mask按照低位到高位的顺序排布）</p><p><img src="`+E+`" alt=""></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 数据类型为int32_t</span></span>
<span class="line"><span>uint64_t mask[1] = {6148914691236517205};</span></span>
<span class="line"><span>// repeatTime = 1, 共64个元素，单次迭代能处理64个元素，故repeatTime = 1。</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内连续读取和写入数据。</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 迭代间的数据连续读取和写入。</span></span>
<span class="line"><span>AscendC::Add(dstLocal, src0Local, src1Local, mask, 1, { 1, 1, 1, 8, 8, 8 });</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(src0Local): [1 2 3 ... 63 64]</span></span>
<span class="line"><span>输入数据(src1Local): [1 2 3 ... 63 64]</span></span>
<span class="line"><span>输出数据(dstLocal): [2 undefined 6 ... 126 undefined]</span></span></code></pre></div><p>mask过程如下：</p><p>mask={6148914691236517205, 0}（注：6148914691236517205表示64位二进制数0b010101....01）</p><p><img src="`+B+'" alt=""></p></li></ul>',16)])])}const P=a(b,[["render",u]]);export{f as __pageData,P as default};
